async function main(inputs) {
  const raw = inputs.apiKey;
  const key = Array.isArray(raw) ? raw[0] : raw;
  if (typeof key !== "string" || key.length === 0) throw new Error("apiKey input missing");
  const response = await fetch("https://api.attio.com/v2/self", { headers: { Authorization: `Bearer ${key}` } });
  const body = await response.json();
  return { httpStatus: response.status, workspaceVerified: response.ok && body.workspace_id === "00000000-0000-4000-8000-000000000020" };
}
